    workflow:[step('Identify opportunity','Identificar oportunidad','Use eligibility signals and payer/current clinical review; do not promise qualification.','Usa señales y revisión vigente; no prometas cualificación.'),step('Educate and consent','Educar y consentir','Explain participation and obtain approved documented consent.','Explica participación y obtiene consentimiento documentado.'),step('Enroll and assign','Inscribir y asignar','Update status and assign the licensed care owner.','Actualiza estado y asigna responsable clínico.'),step('Monthly management','Manejo mensual','Complete documented monitoring, intervention and coordination.','Completa monitoreo, intervención y coordinación documentados.'),step('Review and continue','Revisar y continuar','Clinical review, signature, follow-up and next-month plan.','Revisión clínica, firma, seguimiento y plan siguiente.')],
