    purpose:bilingual('Keep people, access, training, records and operational decisions controlled from onboarding through offboarding.','Mantener personas, accesos, capacitación, expedientes y decisiones controlados desde onboarding hasta offboarding.'),
    responsibilities:{en:['Complete onboarding checklist, role assignment, required training and policy acknowledgment.','Provision least-privilege access with IT and retain approval/audit evidence.','Maintain employment, credential, training and performance records in approved repositories.','Coordinate attendance, leave, coaching and corrective action through authorized processes.','Review role changes promptly and remove access during transfer/offboarding.','Publish controlled policy versions and assign owners/review dates.'],es:['Completar onboarding, rol, capacitación y acuses de política.','Provisionar acceso mínimo con IT y conservar aprobación/auditoría.','Mantener expedientes laborales, credenciales, capacitación y desempeño.','Coordinar asistencia, licencias, coaching y acción correctiva por procesos autorizados.','Revisar cambios de rol y remover accesos al transferir/offboard.','Publicar versiones controladas con responsables y fecha de revisión.']},
    workflow:[step('Authorize role','Autorizar rol','Confirm job, manager, location and approved access profile.','Confirma cargo, supervisor, sede y perfil de acceso.'),step('Onboard','Onboarding','Create accounts, assign training and collect required acknowledgments.','Crea cuentas, asigna cursos y obtiene acuses.'),step('Maintain','Mantener','Track credentials, attendance, performance and role changes.','Rastrea credenciales, asistencia, desempeño y cambios.'),step('Resolve people matters','Resolver asuntos','Use documented coaching, investigation and escalation paths.','Usa rutas documentadas de coaching, investigación y escalamiento.'),step('Offboard','Offboarding','Revoke access, recover assets and preserve records.','Revoca accesos, recupera activos y preserva registros.')],
